package cn.iocoder.yudao.module.facebook.controller.admin.aisearch;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.facebook.controller.admin.aisearch.vo.AiSearchTradeEvidenceSaveReqVO; import cn.iocoder.yudao.module.facebook.controller.admin.aisearch.vo.AiSearchTradeVerifyRespVO; import cn.iocoder.yudao.module.facebook.dal.dataobject.aisearch.AiSearchTradeEvidenceDO; import cn.iocoder.yudao.module.facebook.service.aisearch.AiSearchTradeService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.beans.BeanUtils; import org.springframework.web.bind.annotation.*; import static cn.iocoder.yudao.framework.common.pojo.CommonResult.success;
@Tag(name="管理后台 - AI企业贸易核验") @RestController @RequestMapping("/facebook/ai-search/trade") public class AiSearchTradeController { @Resource private AiSearchTradeService service; @GetMapping("/verify") public CommonResult<AiSearchTradeVerifyRespVO> verify(@RequestParam Long companyId,@RequestParam(required=false) String hsCode,@RequestParam(required=false) String product){return success(service.verify(companyId,hsCode,product));} @PostMapping("/evidence") public CommonResult<Long> saveEvidence(@Valid @RequestBody AiSearchTradeEvidenceSaveReqVO req){ AiSearchTradeEvidenceDO evidence=new AiSearchTradeEvidenceDO(); BeanUtils.copyProperties(req,evidence); return success(service.saveEvidence(evidence)); } }
